                'returned_flow' => 'بعد تصحيح صاحب الطلب وإعادة الإرسال يعود إلى قائمة الانتظار لتكرار المراجعة.',
                'notes' => ['لا يمكن اتخاذ القرار خارج الخطوة الحالية.', 'العرض لا يعني امتلاك صلاحية تعديل بيانات صاحب الطلب.'],
                'timeline' => $flow(['إرسال', 'مراجعة', 'قرار', 'الخطوة التالية'], ['مراجعة', 'قرار']),
                'handoff' => ['from' => 'صاحب الطلب', 'action' => 'قرار اعتماد أو إعادة', 'to' => 'الخطوة التالية'],
            ];
        } elseif ($isView) {
            $guide = [
                'goal' => "الوصول إلى معلومات «{$module}» المصرح بها دون تغيير السجلات التشغيلية.",
                'when' => 'عند الحاجة إلى متابعة الحالة أو قراءة التفاصيل أو إعداد تحليل ضمن نطاق العرض المتاح.',
                'steps' => ["افتح «{$page}».", 'استخدم البحث وعوامل التصفية للوصول إلى الفترة أو السجل المطلوب.', 'افتح التفاصيل واقرأ الحالة والبيانات وسجل التغييرات المتاح.', 'استخدم التقرير أو التصدير فقط إذا ظهر لك الإجراء.', 'ارجع إلى القائمة وغيّر التصفية لمقارنة النتائج.'],
                'after' => 'لا تتغير حالة السجل؛ تستخدم المعلومات للمتابعة أو التقرير فقط.',
                'returned_flow' => 'لا توجد إعادة ضمن صلاحية العرض؛ أبلغ صاحب السجل عبر القناة الإدارية عند ملاحظة خطأ.',
                'notes' => ['عدم ظهور زر تعديل أو اعتماد مقصود لهذا الدور.', 'النتائج تخضع لنطاق الفروع والصلاحيات الحالية.'],
                'timeline' => $flow(['بحث', 'عرض', 'مقارنة', 'تقرير'], ['بحث', 'عرض', 'مقارنة', 'تقرير']),
                'handoff' => ['from' => 'بيانات معتمدة', 'action' => 'عرض وتحليل', 'to' => 'معلومة للمتابعة'],
            ];
        } else {
            $guide = [
                'goal' => "إنجاز مسؤولية {$role['title']} في «{$module}» ضمن حدود الدور الحالية.",
                'when' => "عند وصول مهمة مرتبطة بـ«{$module}» أو ظهور سجل يحتاج إجراءك في «{$page}».",
                'steps' => ["افتح «{$page}» وانتقل إلى «{$module}».", 'استخدم الحالة وعوامل التصفية لتحديد السجل الذي يحتاج إجراء.', 'افتح التفاصيل وراجع البيانات والملاحظات والمرفقات المتاحة.', "نفذ الإجراء الظاهر المرتبط بمسؤوليتك: {$summary}", 'راجع المدخلات ثم احفظ، وتأكد من رسالة النجاح والحالة الجديدة.'],
                'after' => "يحفظ النظام الإجراء ويعرض الحالة التالية وفق مسار «{$module}» دون منح صلاحيات إضافية.",
                'returned_flow' => 'إذا ظهر السجل معاداً، اقرأ سبب الإعادة، صحح الجزء الذي يسمح به دورك ثم أعد الحفظ أو الإرسال عندما يظهر الزر.',
                'notes' => [$role['restrictions'][0], 'الأزرار المتاحة والحالة الحالية هما المرجع للعمل الممكن.', 'لا تنفذ إجراءً بالنيابة عن دور آخر.'],
                'timeline' => $flow(['استلام', 'مراجعة', 'إجراء', 'حفظ', 'تسليم'], ['مراجعة', 'إجراء', 'حفظ']),
                'handoff' => ['from' => $role['receives'][0], 'action' => $summary, 'to' => $role['hands_off'][0]],
            ];
        }

        $role['tasks'][] = $task($module, $summary, match (true) {
            str_contains($module, 'رمضان') => 'fa-moon',
            str_contains($module, 'تقييم') => 'fa-star',
            str_contains($module, 'تقرير') || str_contains($module, 'مؤشر') => 'fa-chart-column',
            str_contains($module, 'صلاح') || str_contains($module, 'إدار') => 'fa-user-shield',
            str_contains($module, 'نقل') || str_contains($module, 'حرك') => 'fa-route',
            str_contains($module, 'صيانة') => 'fa-screwdriver-wrench',
            default => 'fa-list-check',
        }, $guide);
    }
}
unset($role);

return $roles;
